_LOGGER = logging.getLogger(__name__)

CONF_SENSOR_CLASS = 'sensor_class'
DEFAULT_NAME = 'EnOcean Binary Sensor'
DEFAULT_SENSOR_CLASS = 'opening'

PLATFORM_SCHEMA = PLATFORM_SCHEMA.extend({
    vol.Required(CONF_ID): cv.string,
