from PyQt5.QtWidgets import (QApplication, QMainWindow, QTableView, QVBoxLayout, 
                             QWidget, QPushButton, QMenu, QAction, QHeaderView)
from PyQt5.QtCore import Qt, QAbstractTableModel, QModelIndex, QVariant
from PyQt5.QtGui import QColor
import webbrowser

class NetworkModel(QAbstractTableModel):
    def __init__(self, data=None):
        super().__init__()
        self._data = data or []
        self._headers = ['Address', 'Status', 'Type', 'Version']

    def rowCount(self, parent=QModelIndex()):
        return len(self._data)

    def columnCount(self, parent=QModelIndex()):
        return len(self._headers)

    def data(self, index, role=Qt.DisplayRole):
        if not index.isValid():
            return QVariant()

        if role == Qt.DisplayRole:
            row = index.row()
            col = index.column()
            return str(self._data[row][self._headers[col].lower()])

        if role == Qt.BackgroundRole:
            row = index.row()
            status = self._data[row]['status']
            if status == 'Online':
                return QColor(200, 255, 200)
            elif status == 'Offline':
                return QColor(255, 200, 200)

        return QVariant()

    def headerData(self, section, orientation, role=Qt.DisplayRole):
        if role == Qt.DisplayRole and orientation == Qt.Horizontal:
            return self._headers[section]
        return QVariant()

    def update_data(self, new_data):
        self.beginResetModel()
        self._data = new_data
        self.endResetModel()

class NetworkView(QMainWindow):
    def __init__(self, controller):
        super().__init__()
        self.controller = controller
        self.init_ui()

    def init_ui(self):
        self.setWindowTitle('Network Management')
        self.resize(800, 600)

        central_widget = QWidget()
        layout = QVBoxLayout()

        self.table_view = QTableView()
        self.table_view.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        self.table_view.setContextMenuPolicy(Qt.CustomContextMenu)
        self.table_view.customContextMenuRequested.connect(self.node_context_menu)

        refresh_button = QPushButton('Refresh Nodes')
        refresh_button.clicked.connect(self.controller.refresh_nodes_manually)

        layout.addWidget(self.table_view)
        layout.addWidget(refresh_button)

        central_widget.setLayout(layout)
        self.setCentralWidget(central_widget)

    def node_context_menu(self, pos):
        index = self.table_view.indexAt(pos)
        if not index.isValid():
            return

        menu = QMenu(self)
        open_browser_action = QAction('Open in Browser', self)
        open_browser_action.triggered.connect(lambda: self.controller.open_node_in_browser(index))
        menu.addAction(open_browser_action)

        set_root_action = QAction('Set as Root Node', self)
        set_root_action.triggered.connect(lambda: self.controller.set_root_node(index))
        menu.addAction(set_root_action)

        unset_root_action = QAction('Unset Root Node', self)
        unset_root_action.triggered.connect(lambda: self.controller.unset_root_node(index))
        menu.addAction(unset_root_action)

        menu.exec_(self.table_view.viewport().mapToGlobal(pos))

class NetworkController:
    def __init__(self):
        self.model = NetworkModel()
        self.view = NetworkView(self)
        self.view.table_view.setModel(self.model)

    def create(self):
        initial_nodes = [
            {'address': '127.0.0.1', 'status': 'Online', 'type': 'Local', 'version': '1.0'},
            {'address': '192.168.1.100', 'status': 'Offline', 'type': 'Remote', 'version': '0.9'}
        ]
        self.model.update_data(initial_nodes)
        self.view.show()

    def refresh_nodes_manually(self):
        # Simulated node refresh logic
        updated_nodes = [
            {'address': '127.0.0.1', 'status': 'Online', 'type': 'Local', 'version': '1.1'},
            {'address': '192.168.1.101', 'status': 'Online', 'type': 'Remote', 'version': '1.0'}
        ]
        self.model.update_data(updated_nodes)

    def open_node_in_browser(self, index):
        address = self.model._data[index.row()]['address']
        webbrowser.open(f'http://{address}')

    def set_root_node(self, index):
        node = self.model._data[index.row()]
        print(f"Setting {node['address']} as root node")

    def unset_root_node(self, index):
        node = self.model._data[index.row()]
        print(f"Unsetting {node['address']} as root node")

def main():
    app = QApplication(sys.argv)
    controller = NetworkController()
    controller.create()
    sys.exit(app.exec_())

if __name__ == '__main__':
    main()

import numpy as np
import scipy.ndimage as ndimage
from abc import ABC, abstractmethod
from typing import List, Union, Optional, Iterator
from imgmerge.utils import ImageReadFactory

class MergeProcedureVirtual(ABC):
    def __init__(self, images_list: Optional[List[str]] = None):
        self._img_list: List[str] = images_list or []
        self._resimg: Optional[np.ndarray] = None
        self._refimage: Optional[np.ndarray] = None
        self._images_iterator: Optional[Iterator] = None
        self._read_img_factory: ImageReadFactory = ImageReadFactory()

    @property
    def img_list(self) -> List[str]:
        return self._img_list

    @img_list.setter
    def img_list(self, value: List[str]):
        self._img_list = value

    def get_dtype(self, bit_depth: int = 8) -> np.dtype:
        """Determine appropriate numpy data type based on bit depth."""
        dtype_map = {
            8: np.uint8,
            16: np.uint16
        }
        return dtype_map.get(bit_depth, np.uint8)

    def set_images_iterator(self, custom_iterator: Optional[Iterator] = None):
        """Set a custom images iterator."""
        self._images_iterator = custom_iterator or iter(self._img_list)

    def set_images_list(self, images_list: List[str]):
        """Set the list of images to be processed."""
        self._img_list = images_list
        self._images_iterator = iter(images_list)

    def set_reference_image(self, ref_image_path: str):
        """Set a reference image for processing."""
        self._refimage = self._read_img_factory.read_image(ref_image_path)

    def _validate_images(self):
        """Validate image list and iterator."""
        if not self._img_list:
            raise ValueError("No images in list")
        if not self._images_iterator:
            self._images_iterator = iter(self._img_list)

    def _read_next_image(self) -> np.ndarray:
        """Read next image from iterator."""
        try:
            image_path = next(self._images_iterator)
            return self._read_img_factory.read_image(image_path)
        except StopIteration:
            raise StopIteration("No more images to process")

    def _normalize_images(
        self,
        images: Union[List[np.ndarray], np.ndarray],
        target_dtype: np.dtype = np.uint8
    ) -> Union[List[np.ndarray], np.ndarray]:
        """Normalize images to target data type."""
        if isinstance(images, list):
            return [ndimage.zoom(img.astype(target_dtype), 1.0) for img in images]
        return images.astype(target_dtype)

    def _check_image_compatibility(
        self,
        images: Union[List[np.ndarray], np.ndarray],
        ref_image: Optional[np.ndarray] = None
    ) -> bool:
        """Check image compatibility for merging."""
        if ref_image is None:
            ref_image = self._refimage

        if ref_image is None:
            return True

        if isinstance(images, list):
            return all(
                img.shape == ref_image.shape and img.dtype == ref_image.dtype
                for img in images
            )
        return (
            images.shape == ref_image.shape and
            images.dtype == ref_image.dtype
        )

    @abstractmethod
    def execute(self, *args, **kwargs):
        """Abstract method for executing merge procedure."""
        pass

    def process_images(
        self,
        processing_func: Optional[callable] = None,
        *args,
        **kwargs
    ) -> np.ndarray:
        """Generic image processing method."""
        self._validate_images()
        processed_images = []

        while True:
            try:
                current_image = self._read_next_image()
                if processing_func:
                    processed_image = processing_func(current_image, *args, **kwargs)
                    processed_images.append(processed_image)
            except StopIteration:
                break

        return processed_images

