class SpanErrorList(forms.ErrorList):
    def __unicode__(self):
        return self.as_spans()

    def as_spans(self):
        if not self:
            return ''
        return ''.join([f'<span class="error">{error}</span>' for error in self])

class BaseGroupForm(forms.Form):
    ERROR_MESSAGES = {
        'invalid_name': _('Group name contains invalid characters.'),
        'name_exists': _('A group with this name already exists.'),
        'description_long': _('Description exceeds maximum length.'),
        'image_size': _('Image file is too large.'),
        'image_format': _('Invalid image file format.')
    }

    name = forms.CharField(
        max_length=50,
        widget=forms.TextInput(attrs={'class': 'form-control'}),
        error_class=SpanErrorList
    )

    description = forms.CharField(
        required=False,
        max_length=500,
        widget=forms.Textarea(attrs={'class': 'form-control', 'rows': 4}),
        error_class=SpanErrorList
    )

    group_image = forms.ImageField(
        required=False,
        widget=forms.FileInput(attrs={'class': 'form-control-file'}),
        error_class=SpanErrorList
    )

    def clean_name(self):
        name = self.cleaned_data.get('name', '').strip()

        if not re.match(r'^[a-zA-Z0-9\s-]+$', name):
            raise ValidationError(self.ERROR_MESSAGES['invalid_name'])

        # Additional check for existing group name
        if self._check_group_name_exists(name):
            raise ValidationError(self.ERROR_MESSAGES['name_exists'])

        return name

    def clean_description(self):
        description = self.cleaned_data.get('description', '').strip()

        if len(description) > 500:
            raise ValidationError(self.ERROR_MESSAGES['description_long'])

        return description

    def clean_group_image(self):
        image = self.cleaned_data.get('group_image')

        if image:
            if image.size > 5 * 1024 * 1024:  # 5MB limit
                raise ValidationError(self.ERROR_MESSAGES['image_size'])

            try:
                with Image.open(image) as img:
                    if img.format not in ['JPEG', 'PNG', 'GIF']:
                        raise ValidationError(self.ERROR_MESSAGES['image_format'])

                    # Image resizing logic
                    max_size = (800, 800)
                    img.thumbnail(max_size, Image.LANCZOS)

                    filename = f"group_images/{slugify(self.cleaned_data['name'])}.{img.format.lower()}"
                    resized_image = default_storage.save(filename, img)

                    return resized_image
            except Exception:
                raise ValidationError(self.ERROR_MESSAGES['image_format'])

        return None

    def _check_group_name_exists(self, name):
        # Placeholder for group name existence check
        # In a real implementation, this would query the database
        return False

