from __future__ import annotations
from datetime import datetime
from typing import Dict, Optional, Union, Any
import re

class StorageData:
    """
    A flexible data model representing storage information with dynamic attributes
    and robust serialization/deserialization capabilities.
    """
    swagger_types: Dict[str, type] = {
        'name': str,
        'description': Optional[str],
        'comment': Optional[str]
    }

    attribute_map: Dict[str, str] = {
        'name': 'name',
        'description': 'description',
        'comment': 'comment'
    }

    def __init__(
        self, 
        name: str = None, 
        description: Optional[str] = None, 
        comment: Optional[str] = None
    ):
        """
        Initialize StorageData with optional attributes.

        Args:
            name (str): Primary identifier for storage entity
            description (str, optional): Detailed description of storage
            comment (str, optional): Additional commentary on storage
        """
        self._name = None
        self._description = None
        self._comment = None

        if name is not None:
            self.name = name
        if description is not None:
            self.description = description
        if comment is not None:
            self.comment = comment

    @property
    def name(self) -> str:
        """Getter for storage name."""
        return self._name

    @name.setter
    def name(self, value: str) -> None:
        """
        Setter for storage name with validation.

        Args:
            value (str): Name to be set

        Raises:
            ValueError: If name is invalid or empty
        """
        if not value or not isinstance(value, str):
            raise ValueError("Name must be a non-empty string")

        self._name = value.strip()

    @property
    def description(self) -> Optional[str]:
        """Getter for storage description."""
        return self._description

    @description.setter
    def description(self, value: Optional[str]) -> None:
        """
        Setter for storage description with optional validation.

        Args:
            value (str, optional): Description to be set
        """
        if value is not None:
            self._description = str(value).strip()
        else:
            self._description = None

    @property
    def comment(self) -> Optional[str]:
        """Getter for storage comment."""
        return self._comment

    @comment.setter
    def comment(self, value: Optional[str]) -> None:
        """
        Setter for storage comment with optional validation.

        Args:
            value (str, optional): Comment to be set
        """
        if value is not None:
            self._comment = str(value).strip()
        else:
            self._comment = None

    @classmethod
    def from_dict(
        cls, 
        data: Dict[str, Any]
    ) -> StorageData:
        """
        Deserialize dictionary to StorageData instance.

        Args:
            data (Dict): Input dictionary with storage data

        Returns:
            StorageData: Constructed instance from dictionary
        """
        if not data:
            return None

        instance = cls()
        for key, value in data.items():
            if hasattr(instance, key):
                setattr(instance, key, value)

        return instance

    def to_dict(self) -> Dict[str, Any]:
        """
        Convert StorageData to dictionary representation.

        Returns:
            Dict: Serialized storage data
        """
        result = {}
        for attr, _ in self.swagger_types.items():
            value = getattr(self, attr)
            if value is not None:
                result[attr] = value
        return result

    def __repr__(self) -> str:
        """
        String representation of StorageData.

        Returns:
            str: Formatted representation of storage data
        """
        return f"StorageData(name='{self.name}', description='{self.description}', comment='{self.comment}')"

import socket
import threading
import os
import importlib
import sys
import time

class IRCBot:
    def __init__(self, server, port, nickname, channels):
        self.server = server
        self.port = port
        self.nickname = nickname
        self.channels = channels
        self.socket = None
        self.isRunning = True
        self.focusedChannel = None
        self.plugins = {}
        self.pluginDirectory = 'plugins'

    def BYTE(self, msg):
        return msg.encode('utf-8')

    def createMessage(self, command, message):
        full_message = f"{command} {message}\r\n"
        return self.BYTE(full_message)

    def connect(self):
        try:
            self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.socket.connect((self.server, self.port))
            self.socket.send(self.BYTE(f"NICK {self.nickname}\r\n"))
            self.socket.send(self.BYTE(f"USER {self.nickname} 0 * :{self.nickname}\r\n"))

            for channel in self.channels:
                self.socket.send(self.BYTE(f"JOIN {channel}\r\n"))

            self.focusedChannel = self.channels[0] if self.channels else None
        except Exception as e:
            print(f"Connection error: {e}")
            self.reconnect()

    def reconnect(self):
        print("Attempting to reconnect...")
        time.sleep(5)
        self.connect()

    def receive(self):
        try:
            while self.isRunning:
                data = self.socket.recv(2048).decode('utf-8')
                if data.startswith('PING'):
                    self.socket.send(self.BYTE('PONG ' + data.split()[1] + '\r\n'))

                print(data)
        except Exception as e:
            print(f"Receive error: {e}")
            self.reconnect()

    def send_message(self, channel, message):
        if self.socket:
            full_message = f"PRIVMSG {channel} :{message}\r\n"
            self.socket.send(self.BYTE(full_message))

    def load_plugins(self):
        for filename in os.listdir(self.pluginDirectory):
            if filename.endswith('.py'):
                module_name = filename[:-3]
                try:
                    module = importlib.import_module(f"{self.pluginDirectory}.{module_name}")
                    self.plugins[module_name] = module
                    print(f"Loaded plugin: {module_name}")
                except Exception as e:
                    print(f"Error loading plugin {module_name}: {e}")

    def reload_plugins(self):
        for name, module in list(self.plugins.items()):
            try:
                importlib.reload(module)
                print(f"Reloaded plugin: {name}")
            except Exception as e:
                print(f"Error reloading plugin {name}: {e}")

class UserInput(threading.Thread):
    def __init__(self, parent):
        threading.Thread.__init__(self)
        self.parent = parent
        self.daemon = True

    def run(self):
        while self.parent.isRunning:
            try:
                user_input = input()
                self.process_command(user_input)
            except Exception as e:
                print(f"Input error: {e}")

    def process_command(self, command):
        parts = command.split()
        if not parts:
            return

        cmd = parts[0].lower()
        args = parts[1:] if len(parts) > 1 else []

        if cmd == 'join' and args:
            channel = args[0]
            self.parent.socket.send(self.parent.BYTE(f"JOIN {channel}\r\n"))
            self.parent.focusedChannel = channel

        elif cmd == 'leave' and args:
            channel = args[0]
            self.parent.socket.send(self.parent.BYTE(f"PART {channel}\r\n"))

        elif cmd == 'msg' and len(args) >= 2:
            channel = args[0]
            message = ' '.join(args[1:])
            self.parent.send_message(channel, message)

        elif cmd == 'reload':
            self.parent.reload_plugins()

        elif cmd == 'quit':
            self.parent.isRunning = False
            self.parent.socket.close()
            sys.exit(0)

def main():
    bot = IRCBot('irc.freenode.net', 6667, 'PythonBot', ['#testchannel'])
    bot.connect()
    bot.load_plugins()

    receive_thread = threading.Thread(target=bot.receive)
    receive_thread.daemon = True
    receive_thread.start()

    input_thread = UserInput(bot)
    input_thread.start()

    receive_thread.join()

if __name__ == "__main__":
    main()

