class PhylogeneticAnalyzer:
    def __init__(self, config_path=None):
        self.config = self._load_configuration(config_path)
        self.rate_cache = {}
        self.max_retry_attempts = 3

    def _load_configuration(self, config_path):
        default_config = {
            "rate_threshold": 0.05,
            "pi_window_size": 500,
            "informative_site_cutoff": 0.25
        }

        if config_path and os.path.exists(config_path):
            try:
                with open(config_path, 'r') as config_file:
                    user_config = json.load(config_file)
                    default_config.update(user_config)
            except (IOError, json.JSONDecodeError) as e:
                print(f"Configuration load error: {e}")

        return default_config

    def parse_site_rates(self, rate_file):
        for attempt in range(self.max_retry_attempts):
            try:
                with open(rate_file, 'r') as f:
                    site_rates = json.load(f)

                processed_rates = {
                    int(k): float(v) for k, v in site_rates.items()
                    if float(v) > self.config['rate_threshold']
                }

                self.rate_cache[rate_file] = processed_rates
                return processed_rates

            except (IOError, json.JSONDecodeError) as e:
                if attempt == self.max_retry_attempts - 1:
                    print(f"Failed to parse rates after {self.max_retry_attempts} attempts: {e}")
                    return {}
                time.sleep(1)

    def correct_branch_lengths(self, phylogenetic_tree):
        tree = dendropy.Tree.get(
            path=phylogenetic_tree,
            schema='nexus'
        )

        for edge in tree.preorder_edge_iter():
            if edge.length is not None:
                corrected_length = np.log1p(edge.length)
                edge.length = max(corrected_length, 0)

        return tree

    def get_net_pi_for_periods(self, alignment_file, periods=None):
        alignment = dendropy.DnaCharacterMatrix.get(
            path=alignment_file, 
            schema='fasta'
        )

        periods = periods or [
            (0, 500), 
            (500, 1000), 
            (1000, 1500)
        ]

        pi_values = defaultdict(float)

        for start, end in periods:
            subset_alignment = alignment[:, start:end]
            pi_values[(start, end)] = self._calculate_pi(subset_alignment)

        return dict(pi_values)

    def _calculate_pi(self, subset_matrix):
        # Simplified π calculation
        sequences = [str(seq) for seq in subset_matrix]
        seq_length = len(sequences[0])

        total_differences = 0
        total_comparisons = 0

        for i in range(len(sequences)):
            for j in range(i+1, len(sequences)):
                seq1, seq2 = sequences[i], sequences[j]
                differences = sum(a != b for a, b in zip(seq1, seq2))
                total_differences += differences
                total_comparisons += 1

        return total_differences / (total_comparisons * seq_length) if total_comparisons else 0

    def get_informative_sites(self, alignment_path):
        matrix = dendropy.DnaCharacterMatrix.get(
            path=alignment_path, 
            schema='fasta'
        )

        site_information = {}

        for site_index in range(len(matrix)):
            site_frequencies = self._calculate_site_frequencies(matrix, site_index)
            informativeness = self._assess_site_informativeness(site_frequencies)

            site_information[site_index] = {
                'frequencies': site_frequencies,
                'informative': informativeness > self.config['informative_site_cutoff']
            }

        return site_information

    def _calculate_site_frequencies(self, matrix, site_index):
        site_data = [str(seq)[site_index] for seq in matrix]
        return {base: site_data.count(base) / len(site_data) for base in set(site_data)}

    def _assess_site_informativeness(self, frequencies):
        sorted_freqs = sorted(frequencies.values(), reverse=True)
        return 1 - sorted_freqs[0] if sorted_freqs else 0

    def cull_uninformative_rates(self, rates):
        return {
            site: rate 
            for site, rate in rates.items() 
            if rate > self.config['rate_threshold']
        }

