class PluginManager:
    def __init__(self):
        self.plugins = {}
        self.plugin_paths = []
        self.loaded_plugins = {}
        self.__version__ = '1.2.3'
        self.__author__ = 'Bot Framework Team'
        self.__contributors__ = ['John Doe', 'Jane Smith']

    def discover_plugins(self, search_paths=None):
        """
        Discover available plugins in specified paths
        """
        paths = search_paths or self.plugin_paths
        discovered_plugins = {}
        for path in paths:
            for item in os.listdir(path):
                if item.endswith('.py') and not item.startswith('__'):
                    module_name = item[:-3]
                    discovered_plugins[module_name] = os.path.join(path, item)
        return discovered_plugins

    def load_plugin(self, plugin_name, path=None):
        """
        Load a specific plugin dynamically
        """
        try:
            if path is None:
                path = self.find_plugin_path(plugin_name)

            module = imp.load_source(plugin_name, path)
            self.loaded_plugins[plugin_name] = module
            return module
        except Exception as e:
            print(f"Error loading plugin {plugin_name}: {e}")
            return None

    def reload_plugin(self, plugin_name):
        """
        Reload a specific plugin
        """
        if plugin_name in self.loaded_plugins:
            try:
                imp.reload(self.loaded_plugins[plugin_name])
                return True
            except Exception as e:
                print(f"Reload failed for {plugin_name}: {e}")
                return False
        return False

    def configure_plugin(self, plugin_name, config_dict):
        """
        Configure plugin with provided settings
        """
        if plugin_name in self.loaded_plugins:
            plugin_module = self.loaded_plugins[plugin_name]
            for key, value in config_dict.items():
                setattr(plugin_module, key, value)
            return True
        return False

    def find_plugin_path(self, plugin_name):
        """
        Find plugin path by name
        """
        for path in self.plugin_paths:
            potential_path = os.path.join(path, f"{plugin_name}.py")
            if os.path.exists(potential_path):
                return potential_path
        return None

    def list_plugins(self):
        """
        List all discovered and loaded plugins
        """
        return {
            'discovered': list(self.discover_plugins().keys()),
            'loaded': list(self.loaded_plugins.keys())
        }

    def test_plugin(self, plugin_name):
        """
        Basic plugin testing mechanism
        """
        plugin_module = self.loaded_plugins.get(plugin_name)
        if plugin_module and hasattr(plugin_module, 'test'):
            return plugin_module.test()
        return False

    def install_plugin(self, plugin_url):
        """
        Download and install plugin from remote source
        """
        try:
            # Placeholder for actual plugin download logic
            plugin_name = os.path.basename(plugin_url)
            return self.load_plugin(plugin_name)
        except Exception as e:
            print(f"Plugin installation failed: {e}")
            return None

