import plt
import ipp
import os
import string

class trace:
    def __init__(self, filename):
        self.filename = filename
        self.test_dict = {}
        self.packet_count = 0
        self.total_bytes = 0

    def print_first(self, data, length=16):
        hex_data = ' '.join([f'{byte:02x}' for byte in data[:length]])
        print(f"First {length} bytes: {hex_data}")

    def ca2str(self, char_array):
        return ''.join(chr(byte) for byte in char_array if byte != 0)

    def process_trace(self):
        try:
            with plt.trace(self.filename) as trace_file:
                for packet in trace_file:
                    self.packet_count += 1
                    self.total_bytes += packet.len

                    # Extract IP metadata
                    ip = packet.ip
                    if ip:
                        sa = ipp.prefix(ip.src_addr)
                        da = ipp.prefix(ip.dst_addr)

                        # Track address pair occurrences
                        addr_pair = (sa, da)
                        self.test_dict[addr_pair] = self.test_dict.get(addr_pair, 0) + 1

                        # Print detailed packet information
                        print(f"Packet {self.packet_count}:")
                        print(f"  Timestamp: {packet.ts}")
                        print(f"  Length: {packet.len} bytes")
                        print(f"  Source: {sa}")
                        print(f"  Destination: {da}")

                        # Optional: Print first bytes of packet data
                        if packet.data:
                            self.print_first(packet.data)

                        print("-" * 40)

        except Exception as e:
            print(f"Error processing trace file: {e}")

    def print_address_summary(self):
        print("\nAddress Pair Occurrences:")
        sorted_pairs = sorted(self.test_dict.items(), key=lambda x: x[1], reverse=True)

        for (src, dst), count in sorted_pairs[:10]:
            print(f"  {src} -> {dst}: {count} packets")

    def generate_report(self):
        print("\nTrace File Summary:")
        print(f"Total Packets: {self.packet_count}")
        print(f"Total Bytes: {self.total_bytes}")
        print(f"Unique Address Pairs: {len(self.test_dict)}")

def detect_os_path():
    os_paths = {
        'Windows': r'C:\network_traces\',
        'Darwin': '/Users/admin/network_traces/',
        'Linux': '/home/user/network_traces/'
    }
    return os_paths.get(os.name, '/default/trace/path/')

def main():
    trace_dir = detect_os_path()
    trace_files = [
        'network_capture_01.pcap',
        'network_capture_02.erf',
        'network_capture_03.pcap'
    ]

    for filename in trace_files:
        full_path = os.path.join(trace_dir, filename)

        print(f"\nProcessing Trace File: {filename}")
        print("=" * 40)

        network_trace = trace(full_path)
        network_trace.process_trace()
        network_trace.print_address_summary()
        network_trace.generate_report()

if __name__ == "__main__":
    main()

#!/usr/bin/env python
# Cloud User Group Management Utility for Eucalyptus

import sys
import optparse
import boto.ec2
from boto.ec2.regioninfo import RegionInfo
from euca_admin import EucaAdmin

class GroupManagementError(Exception):
    """Custom exception for group management errors."""
    pass

class Group:
    """Represents a cloud user group with management capabilities."""

    def __init__(self, connection, group_name):
        """Initialize group with connection and name."""
        self.connection = connection
        self.group_name = group_name
        self.users = []
        self.authorizations = []

    def describe(self):
        """Retrieve and return detailed group information."""
        try:
            result = self.connection.describe_groups(groupnames=[self.group_name])
            if not result:
                raise GroupManagementError(f"Group {self.group_name} not found")

            group_details = result[0]
            return {
                'group_name': group_details.name,
                'users': group_details.users,
                'description': group_details.description
            }
        except Exception as e:
            raise GroupManagementError(f"Error describing group: {str(e)}")

    def add_users(self, users):
        """Add users to the group."""
        try:
            for user in users:
                self.connection.add_user_to_group(self.group_name, user)
            return True
        except Exception as e:
            raise GroupManagementError(f"Error adding users: {str(e)}")

    def delete_group(self):
        """Delete the current group."""
        try:
            self.connection.delete_group(self.group_name)
            return True
        except Exception as e:
            raise GroupManagementError(f"Error deleting group: {str(e)}")

class EucalyptusGroupManager:
    """Manages group operations in Eucalyptus cloud environment."""

    def __init__(self, access_key, secret_key, url):
        """Initialize Eucalyptus connection."""
        try:
            region = RegionInfo(name='eucalyptus', endpoint=url)
            self.connection = boto.ec2.connection.EC2Connection(
                aws_access_key_id=access_key,
                aws_secret_access_key=secret_key,
                region=region,
                is_secure=False
            )
        except Exception as e:
            raise GroupManagementError(f"Connection error: {str(e)}")

    def group_describe(self, group_name):
        """Describe a specific group."""
        group = Group(self.connection, group_name)
        return group.describe()

    def group_add(self, group_name, users):
        """Add a group and its users."""
        try:
            self.connection.create_group(group_name)
            group = Group(self.connection, group_name)
            group.add_users(users)
            return True
        except Exception as e:
            raise GroupManagementError(f"Group creation error: {str(e)}")

    def group_delete(self, group_name):
        """Delete a group."""
        group = Group(self.connection, group_name)
        return group.delete_group()

def parse_arguments():
    """Parse command-line arguments."""
    parser = optparse.OptionParser(description='Eucalyptus Cloud Group Management')
    parser.add_option('-d', '--describe', action='store_true', help='Describe group')
    parser.add_option('-a', '--add', action='store_true', help='Add group')
    parser.add_option('-r', '--remove', action='store_true', help='Delete group')
    parser.add_option('-g', '--group', dest='group_name', help='Group name')
    parser.add_option('-u', '--users', dest='users', help='Users (comma-separated)')

    return parser.parse_args()

def main():
    """Main execution method for CLI interface."""
    options, args = parse_arguments()

    try:
        # Replace with actual credentials and URL
        manager = EucalyptusGroupManager(
            access_key='YOUR_ACCESS_KEY',
            secret_key='YOUR_SECRET_KEY',
            url='your.eucalyptus.endpoint'
        )

        if options.describe and options.group_name:
            result = manager.group_describe(options.group_name)
            print("Group Details:", result)

        elif options.add and options.group_name and options.users:
            users = options.users.split(',')
            result = manager.group_add(options.group_name, users)
            print(f"Group {options.group_name} created successfully")

        elif options.remove and options.group_name:
            result = manager.group_delete(options.group_name)
            print(f"Group {options.group_name} deleted successfully")

        else:
            print("Invalid arguments. Use -h for help.")

    except GroupManagementError as e:
        print(f"Error: {str(e)}")
        sys.exit(1)

if __name__ == '__main__':
    main()

import json
import motor.motor_tornado
import tornado.gen
from bson import ObjectId
from datetime import datetime

class MongoDbService:
    def __init__(self, uri_connection, database, collection):
        self.client = motor.motor_tornado.MotorClient(uri_connection)
        self.database = self.client[database]
        self.collection = self.database[collection]

    def json_default(self, obj):
        """Custom JSON serialization for complex types."""
        if isinstance(obj, ObjectId):
            return str(obj)
        if isinstance(obj, datetime):
            return obj.isoformat()
        raise TypeError(f"Object of type {type(obj)} is not JSON serializable")

    def json_dumps(self, data):
        """Custom JSON dump method with extended serialization."""
        return json.dumps(data, default=self.json_default)

    def json_loads(self, data):
        """Safely parse JSON string to object."""
        try:
            return json.loads(data)
        except json.JSONDecodeError:
            return None

    @tornado.gen.coroutine
    def insert(self, document):
        """
        Asynchronously insert a document into the collection.

        Args:
            document (dict): Document to be inserted

        Returns:
            ObjectId of inserted document
        """
        try:
            result = yield self.collection.insert_one(document)
            return result.inserted_id
        except Exception as e:
            print(f"Insert Error: {e}")
            return None

    @tornado.gen.coroutine
    def update(self, filter_query, update_data, upsert=False):
        """
        Asynchronously update documents in the collection.

        Args:
            filter_query (dict): Criteria for document selection
            update_data (dict): Update operation details
            upsert (bool): Create document if not exists

        Returns:
            Number of modified documents
        """
        try:
            result = yield self.collection.update_many(
                filter_query, 
                {'$set': update_data}, 
                upsert=upsert
            )
            return result.modified_count
        except Exception as e:
            print(f"Update Error: {e}")
            return 0

    @tornado.gen.coroutine
    def find(self, 
             filter_query=None, 
             projection=None, 
             limit=50, 
             skip=0, 
             sort_key=None, 
             sort_order=1):
        """
        Asynchronously retrieve documents with flexible querying.

        Args:
            filter_query (dict): Query criteria
            projection (dict): Fields to include/exclude
            limit (int): Maximum documents to return
            skip (int): Number of documents to skip
            sort_key (str): Field to sort by
            sort_order (int): Sort direction (1: ascending, -1: descending)

        Returns:
            List of matching documents
        """
        try:
            query_filter = filter_query or {}
            query_projection = projection or {}

            cursor = self.collection.find(query_filter, query_projection)

            if sort_key:
                cursor.sort(sort_key, sort_order)

            cursor.skip(skip).limit(limit)

            results = yield cursor.to_list(length=limit)
            return results
        except Exception as e:
            print(f"Query Error: {e}")
            return []

    @tornado.gen.coroutine
    def delete(self, filter_query):
        """
        Asynchronously delete documents from the collection.

        Args:
            filter_query (dict): Deletion criteria

        Returns:
            Number of deleted documents
        """
        try:
            result = yield self.collection.delete_many(filter_query)
            return result.deleted_count
        except Exception as e:
            print(f"Delete Error: {e}")
            return 0

    def close_connection(self):
        """Close MongoDB connection."""
        self.client.close()

from django.db import models
from sampledatahelper.helper import SampleDataHelper

class Register:
    _instance = None
    _initialized = False

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(Register, cls).__new__(cls)
        return cls._instance

    def __init__(self):
        if not self._initialized:
            self.sd = SampleDataHelper()
            self.fields = {}
            self.ignored_fields = []
            self._initialized = True

    def register(self, field_type, handler=None):
        """
        Register a handler for a specific field type
        If no handler provided, use default generator
        """
        def default_handler(field):
            if isinstance(field, models.CharField):
                return self.sd.name()
            elif isinstance(field, models.IntegerField):
                return self.sd.integer(1, 100)
            elif isinstance(field, models.FloatField):
                return self.sd.float(1, 100)
            elif isinstance(field, models.EmailField):
                return self.sd.email()
            elif isinstance(field, models.DateTimeField):
                return self.sd.datetime()
            elif isinstance(field, models.BooleanField):
                return self.sd.boolean()
            return None

        handler = handler or default_handler
        self.fields[field_type] = handler
        return self

    def ignore(self, *field_types):
        """
        Ignore specific field types during sample data generation
        """
        self.ignored_fields.extend(field_types)
        return self

    def get_handler(self, field):
        """
        Retrieve appropriate handler for a given field
        """
        field_type = type(field)

        if field_type in self.ignored_fields:
            return None

        for registered_type, handler in self.fields.items():
            if issubclass(field_type, registered_type):
                return handler

        return None

register = Register()

# Example usage and configuration
register.register(models.CharField) \
    .register(models.IntegerField) \
    .register(models.EmailField) \
    .ignore(models.AutoField, models.ForeignKey)

import logging
import json
import traceback
import time
from google.appengine.api import mail
from google.appengine.api import capabilities
from google.appengine.runtime import apiproxy_errors

class EmailMiddleware:
    def __init__(self, get_response=None):
        self.get_response = get_response
        self.logger = logging.getLogger(__name__)

    def get_apis_statuses(self):
        """Check status of critical Google App Engine APIs."""
        api_checks = {
            'datastore': capabilities.CapabilitySet('datastore_v3', ['write']),
            'memcache': capabilities.CapabilitySet('memcache', ['write']),
            'mail': capabilities.CapabilitySet('mail', ['send'])
        }

        api_statuses = {}
        for name, api in api_checks.items():
            try:
                api_statuses[name] = {
                    'available': api.is_enabled(),
                    'status': 'Operational' if api.is_enabled() else 'Unavailable'
                }
            except Exception as e:
                api_statuses[name] = {
                    'available': False,
                    'status': f'Error checking status: {str(e)}'
                }

        return api_statuses

    def send_error_to_admins(self, error_data):
        """Send detailed error report to application administrators."""
        try:
            subject = f"Application Error: {error_data.get('error_type', 'Unknown')}"
            body = self.format_error_email(error_data)

            mail.send_mail(
                sender='system@yourdomain.com',
                to='admin@yourdomain.com',
                subject=subject,
                body=body
            )
        except Exception as email_error:
            self.logger.error(f"Failed to send admin email: {email_error}")

    def format_error_email(self, error_data):
        """Create a structured error report for email."""
        email_template = """
        Error Report
        ------------
        Type: {error_type}
        Timestamp: {timestamp}

        Request Details:
        - Path: {request_path}
        - Method: {request_method}
        - Parameters: {request_params}

        API Status:
        {api_status}

        Stack Trace:
        {stack_trace}
        """

        return email_template.format(**error_data)

    def process_exception(self, request, error):
        """Central error processing and reporting method."""
        error_data = {
            'error_type': type(error).__name__,
            'timestamp': time.strftime("%Y-%m-%d %H:%M:%S"),
            'request_path': request.path,
            'request_method': request.method,
            'request_params': json.dumps(request.GET.dict()),
            'api_status': json.dumps(self.get_apis_statuses(), indent=2),
            'stack_trace': traceback.format_exc()
        }

        # Log the error
        self.logger.error(f"Error: {error_data['error_type']} - {error}")

        # Send admin notification
        self.send_error_to_admins(error_data)

        # Render appropriate error template
        if isinstance(error, apiproxy_errors.OverQuotaError):
            return self.render_quota_exceeded_page()
        elif isinstance(error, Exception):
            return self.render_generic_error_page(error)

    def render_quota_exceeded_page(self):
        """Render a specific template for quota exceeded scenarios."""
        return {
            'status': 503,
            'template': 'errors/quota_exceeded.html',
            'context': {'message': 'Service temporarily unavailable'}
        }

    def render_generic_error_page(self, error):
        """Render a generic error template."""
        return {
            'status': 500,
            'template': 'errors/generic.html',
            'context': {'error': str(error)}
        }

    def __call__(self, request):
        """Middleware entry point for processing requests."""
        try:
            response = self.get_response(request)
            return response
        except Exception as error:
            return self.process_exception(request, error)

