import sys
from PyQt5.QtCore import Qt, QAbstractTableModel, QModelIndex
from PyQt5.QtWidgets import QApplication, QMainWindow, QTableView, QVBoxLayout, QWidget

class MyData:
    def __init__(self, rows=5, columns=3):
        self._data = [[f"Cell {row},{col}" for col in range(columns)] for row in range(rows)]
        self._change_callback = None

    def get_num_rows(self):
        return len(self._data)

    def get_num_columns(self):
        return len(self._data[0]) if self._data else 0

    def get_data(self):
        return self._data

    def set_data(self, row, col, value):
        if 0 <= row < self.get_num_rows() and 0 <= col < self.get_num_columns():
            self._data[row][col] = value
            if self._change_callback:
                self._change_callback(row, col)

    def register_change_callback(self, callback):
        self._change_callback = callback

class MyModel(QAbstractTableModel):
    def __init__(self, data):
        super().__init__()
        self._data = data

    def rowCount(self, parent=QModelIndex()):
        return self._data.get_num_rows()

    def columnCount(self, parent=QModelIndex()):
        return self._data.get_num_columns()

    def data(self, index, role=Qt.DisplayRole):
        if not index.isValid():
            return None

        if role == Qt.DisplayRole or role == Qt.EditRole:
            row = index.row()
            col = index.column()
            return str(self._data.get_data()[row][col])

        return None

    def setData(self, index, value, role=Qt.EditRole):
        if role == Qt.EditRole:
            row = index.row()
            col = index.column()
            self._data.set_data(row, col, value)
            self.dataChanged.emit(index, index)
            return True
        return False

    def flags(self, index):
        return Qt.ItemIsSelectable | Qt.ItemIsEnabled | Qt.ItemIsEditable

    def changedCallback(self, row, col):
        print(f"Data changed at row {row}, column {col}")

class MainWindow(QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle("Dynamic Table Model")
        self.setGeometry(100, 100, 600, 400)

        # Create central widget and layout
        central_widget = QWidget()
        layout = QVBoxLayout()
        central_widget.setLayout(layout)
        self.setCentralWidget(central_widget)

        # Create data and model
        self.my_data = MyData()
        self.my_data.register_change_callback(self.my_data.changedCallback)
        self.model = MyModel(self.my_data)

        # Create table view
        self.table_view = QTableView()
        self.table_view.setModel(self.model)
        layout.addWidget(self.table_view)

def main():
    app = QApplication(sys.argv)
    window = MainWindow()
    window.show()
    sys.exit(app.exec_())

if __name__ == "__main__":
    main()

import hashlib
import jwt
import six.moves.urllib.parse
from sentry.shared_integrations.exceptions import ApiError

class JiraTenant:
    def __init__(self, client_key, shared_secret):
        self.client_key = client_key
        self.shared_secret = shared_secret

def percent_encode(value):
    """Custom percent-encoding for URL parameters."""
    if value is None:
        return ''
    encoded_value = six.moves.urllib.parse.quote(str(value), safe='~')
    return encoded_value.replace('+', '%20').replace('*', '%2A')

def get_query_hash(request, method='GET'):
    """Generate secure query hash for request validation."""
    parsed_url = six.moves.urllib.parse.urlparse(request.url)
    query_params = six.moves.urllib.parse.parse_qs(parsed_url.query, keep_blank_values=True)

    sorted_params = sorted(
        (key, value[0] if isinstance(value, list) else value)
        for key, value in query_params.items()
    )

    canonical_params = '&'.join(
        f"{percent_encode(key)}={percent_encode(value)}"
        for key, value in sorted_params
    )

    canonical_uri = percent_encode(parsed_url.path)
    qsh_base = f"{method.upper()}:{canonical_uri}:{canonical_params}"
    return hashlib.sha256(qsh_base.encode('utf-8')).hexdigest()

def get_jira_auth_from_request(request, tenant_lookup_fn):
    """Extract and validate Jira authentication from request."""
    try:
        token = request.GET.get('jwt')
        if not token:
            raise ApiError('Missing JWT token')

        # Decode token without verification
        try:
            decoded = jwt.decode(token, verify=False)
        except jwt.DecodeError:
            raise ApiError('Invalid JWT token')

        # Extract token metadata
        issuer = decoded.get('iss')
        qsh = decoded.get('qsh')

        # Validate query hash
        computed_qsh = get_query_hash(request)
        if qsh != computed_qsh:
            raise ApiError('Invalid query hash')

        # Retrieve tenant authentication details
        tenant = tenant_lookup_fn(issuer)
        if not tenant:
            raise ApiError('Unknown Jira tenant')

        # Verify JWT signature
        try:
            jwt.decode(
                token,
                tenant.shared_secret,
                algorithms=['HS256'],
                audience=tenant.client_key
            )
        except jwt.InvalidTokenError:
            raise ApiError('Invalid JWT signature')

        return tenant

    except Exception as e:
        raise ApiError(f'Authentication error: {str(e)}')

def default_tenant_lookup(issuer):
    """Default tenant lookup implementation."""
    # Placeholder for actual tenant retrieval logic
    return JiraTenant(
        client_key=issuer,
        shared_secret='your_default_secret'
    )

def jira_authentication_handler(request):
    """Main authentication handler for Jira integration."""
    try:
        # Use default or custom tenant lookup function
        tenant = get_jira_auth_from_request(request, default_tenant_lookup)
        return {
            'authenticated': True,
            'tenant_id': tenant.client_key
        }
    except ApiError as auth_error:
        return {
            'authenticated': False,
            'error': str(auth_error)
        }

import unittest

def get_headers(data_matrix):
    """
    Extract unique headers from a list of dictionaries.

    Args:
        data_matrix (list): List of dictionaries with potentially varying structures.

    Returns:
        list: Unique headers from all dictionaries.
    """
    if not data_matrix:
        return []

    unique_headers = set()
    for item in data_matrix:
        unique_headers.update(item.keys())

    return sorted(list(unique_headers))

def column_size(data_matrix):
    """
    Calculate maximum column width for each header.

    Args:
        data_matrix (list): List of dictionaries with data.

    Returns:
        dict: Maximum column width for each header.
    """
    if not data_matrix:
        return {}

    headers = get_headers(data_matrix)
    column_widths = {header: len(str(header)) for header in headers}

    for item in data_matrix:
        for header in headers:
            value = item.get(header, '')
            column_widths[header] = max(
                column_widths[header], 
                len(str(value))
            )

    return column_widths

class TestDisplay(unittest.TestCase):
    def test_headers_empty_matrix(self):
        """Test header extraction with an empty matrix."""
        self.assertEqual(get_headers([]), [])

    def test_headers_consistent_dicts(self):
        """Test header extraction with consistent dictionaries."""
        data = [
            {'name': 'Alice', 'age': 30},
            {'name': 'Bob', 'age': 25}
        ]
        expected_headers = ['age', 'name']
        self.assertEqual(get_headers(data), expected_headers)

    def test_headers_different_structures(self):
        """Test header extraction with varying dictionary structures."""
        data = [
            {'name': 'Alice', 'age': 30},
            {'city': 'New York', 'country': 'USA'},
            {'job': 'Engineer', 'salary': 75000}
        ]
        expected_headers = ['age', 'city', 'country', 'job', 'name', 'salary']
        self.assertEqual(get_headers(data), expected_headers)

    def test_column_size_basic(self):
        """Test basic column size calculation."""
        data = [
            {'name': 'Alice', 'age': 30},
            {'name': 'Bob', 'age': 25}
        ]
        expected_sizes = {
            'name': 5,
            'age': 3
        }
        self.assertEqual(column_size(data), expected_sizes)

    def test_column_size_with_different_types(self):
        """Test column size with different data types."""
        data = [
            {'name': 'Alice', 'active': True},
            {'name': 'Bob', 'active': False}
        ]
        expected_sizes = {
            'name': 5,
            'active': 5
        }
        self.assertEqual(column_size(data), expected_sizes)

    def test_column_size_with_long_data(self):
        """Test column size with longer data entries."""
        data = [
            {'name': 'Verylongname', 'age': 30},
            {'name': 'Bob', 'age': 25000}
        ]
        expected_sizes = {
            'name': 12,
            'age': 5
        }
        self.assertEqual(column_size(data), expected_sizes)

if __name__ == '__main__':
    unittest.main()

import nova
import ryu
import cfg
import utils
import linux_net
import iptables
import logging
import subprocess
from ryu.app.ofctl import api as ryu_api
from ryu.lib.packet import ethernet
from ryu.ofproto import ofproto_v1_3 as ofproto

LOG = logging.getLogger(__name__)

ryu_linux_net_opt = cfg.BoolOpt(
    'ryu_use_linux_net',
    default=True,
    help='Enable Ryu Linux network integration'
)

FLAGS = cfg.CONF
FLAGS.register_opt(ryu_linux_net_opt)

class OFPClient(object):
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.client = ryu_api.get_ofctl_client()

    def _get_datapath_id(self, bridge_name):
        try:
            output = subprocess.check_output(
                ['ovs-vsctl', 'get', 'Bridge', bridge_name, 'datapath_id']
            ).strip().decode('utf-8')
            return output.replace('"', '')
        except subprocess.CalledProcessError:
            LOG.error(f"Failed to retrieve datapath ID for {bridge_name}")
            return None

    def _get_port_no(self, bridge_name, port_name):
        try:
            output = subprocess.check_output(
                ['ovs-vsctl', 'get', 'Interface', port_name, 'ofport']
            ).strip().decode('utf-8')
            return int(output)
        except subprocess.CalledProcessError:
            LOG.error(f"Failed to retrieve port number for {port_name}")
            return None

class LinuxOVSRyuInterfaceDriver(nova.network.linux_net.LinuxOVSInterfaceDriver):
    def __init__(self, *args, **kwargs):
        super(LinuxOVSRyuInterfaceDriver, self).__init__(*args, **kwargs)
        self.ofp_client = OFPClient(
            FLAGS.ryu_api_host,
            FLAGS.ryu_api_port
        )

    def plug(self, network, mac_address, port_id, host=None):
        bridge_name = self._get_bridge_name(network['id'])
        dev = self._get_dev_name(port_id)

        try:
            linux_net.create_ovs_vif_port(
                bridge_name, dev, port_id, mac_address
            )

            datapath_id = self.ofp_client._get_datapath_id(bridge_name)
            port_no = self.ofp_client._get_port_no(bridge_name, dev)

            if datapath_id and port_no:
                self._register_port_with_ryu(datapath_id, port_no, mac_address)
                self._configure_security_rules(dev)

        except Exception as e:
            LOG.error(f"Network interface plug failed: {e}")
            raise

    def _register_port_with_ryu(self, datapath_id, port_no, mac_address):
        try:
            ryu_api.send_port_mod(
                datapath_id,
                port_no,
                mac_address,
                ofproto.OFPFC_ADD
            )
        except Exception as e:
            LOG.warning(f"Ryu port registration failed: {e}")

    def _configure_security_rules(self, dev):
        try:
            iptables.add_filter_rules(dev)
            iptables.add_security_group_rules(dev)
        except Exception as e:
            LOG.error(f"Security rule configuration failed: {e}")

    def _get_bridge_name(self, network_id):
        return f"br-{network_id}"

    def _get_dev_name(self, port_id):
        return f"tap{port_id[:11]}"

def initialize_driver():
    driver = LinuxOVSRyuInterfaceDriver()
    return driver

