import math
import Foundation

def angle(point1, point2):
    """Calculate angle between two points."""
    dx = point2.x - point1.x
    dy = point2.y - point1.y
    return math.degrees(math.atan2(dy, dx))

def normalize_angle(angle_degrees):
    """Normalize angle to standard range."""
    while angle_degrees < 0:
        angle_degrees += 180
    while angle_degrees >= 180:
        angle_degrees -= 180
    return angle_degrees

def midpoint(point1, point2):
    """Calculate midpoint between two points."""
    return Foundation.NSPoint(
        x=(point1.x + point2.x) / 2,
        y=(point1.y + point2.y) / 2
    )

def is_there_already_a_guide_with_these_properties(layer, angle, position):
    """Check if a guide with similar properties already exists."""
    for guide in layer.guides:
        if (abs(guide.angle - angle) < 0.1 and 
            math.dist((guide.position.x, guide.position.y), 
                      (position.x, position.y)) < 1):
            return True
    return False

def create_smart_guides():
    """Generate smart guides based on selected points."""
    font = Glyphs.font

    if not font:
        print("No font open.")
        return

    # Process each selected layer
    for layer in font.selectedLayers:
        selected_points = [p for p in layer.selection if isinstance(p, GSNode)]

        # Validate point selection
        if len(selected_points) < 2:
            print("Select at least two points.")
            continue

        # Process point combinations
        for i in range(len(selected_points)):
            for j in range(i+1, len(selected_points)):
                point1 = selected_points[i]
                point2 = selected_points[j]

                # Calculate guide properties
                line_angle = normalize_angle(angle(point1, point2))
                line_midpoint = midpoint(point1, point2)

                # Perpendicular line angle
                perp_angle = normalize_angle(line_angle + 90)

                # Vertical and horizontal guides
                guide_angles = [line_angle, perp_angle]

                for guide_angle in guide_angles:
                    if not is_there_already_a_guide_with_these_properties(layer, guide_angle, line_midpoint):
                        new_guide = GSGuide()
                        new_guide.angle = guide_angle
                        new_guide.position = line_midpoint
                        layer.guides.append(new_guide)

    print("Smart guides created successfully!")

# Plugin initialization
def __init__(self):
    try:
        Glyphs.registerDefault('com.example.smartguides', {
            'version': '1.0',
            'description': 'Intelligent guide generation'
        })
    except Exception as e:
        print(f"Initialization error: {e}")

# Main execution
if __name__ == '__main__':
    try:
        create_smart_guides()
    except Exception as e:
        print(f"Error generating smart guides: {e}")

