            self.add_topping(key)

        elif storage.screen == "remove":
            self.remove_topping(key)

    def add_topping(self, key):
        if key == "return":
            storage.screen = "remove"
            pyaudiogame.say("Switching to topping removal mode. Current toppings:")
            for i, topping in enumerate(storage.your_toppings, 1):
                pyaudiogame.say(f"{i}. {topping}")
            pyaudiogame.say("Enter the number of the topping you want to remove.")

        elif is_number(key):
            index = int(key) - 1
            if 0 <= index < len(storage.toppings):
                topping = storage.toppings[index]
                if topping not in storage.your_toppings:
                    storage.your_toppings.append(topping)
                    pyaudiogame.say(f"Added {topping} to your pizza.")
                else:
                    pyaudiogame.say(f"{topping} is already on your pizza.")
            else:
                pyaudiogame.say("Invalid topping number.")

    def remove_topping(self, key):
        if key == "return":
            storage.screen = "eat"
            pyaudiogame.say("Ready to eat your pizza! Your toppings are:")
            for topping in storage.your_toppings:
                pyaudiogame.say(topping)
            pyaudiogame.say("Press enter to eat your pizza.")

        elif is_number(key):
            index = int(key) - 1
            if 0 <= index < len(storage.your_toppings):
                topping = storage.your_toppings[index]
                if topping != "cheese":
                    storage.your_toppings.remove(topping)
                    pyaudiogame.say(f"Removed {topping} from your pizza.")
                else:
                    pyaudiogame.say("Cannot remove cheese, it's the base of your pizza!")
            else:
                pyaudiogame.say("Invalid topping number.")

    def on_end(self):
        if storage.screen == "eat":
            pyaudiogame.say("Enjoy your delicious pizza!")

pyaudiogame.start(MyApp)

#!/usr/bin/env python3
import os
import sys
import subprocess
import argparse
import shutil

class VOLT:
    class Command:
        @staticmethod
        def decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

    class Server:
        @staticmethod
        def start(classpath=None):
            cmd = ['voltdb', 'create']
            if classpath:
                cmd.extend(['-C', classpath])
            subprocess.run(cmd, check=True)

    class Java:
        @staticmethod
        def compile(sources, classpath=None):
            cmd = ['javac', '-cp']
            if classpath:
                cmd.append(classpath)
            cmd.extend(sources)
            subprocess.run(cmd, check=True)

class VoterBenchmarkRunner:
    def __init__(self):
        self.base_dir = os.path.dirname(os.path.abspath(__file__))
        self.build_dir = os.path.join(self.base_dir, 'build')
        self.src_dir = os.path.join(self.base_dir, 'src')
        self.voltdb_home = os.environ.get('VOLTDB_HOME', '/opt/voltdb')

    @VOLT.Command.decorator
    def build(self, clean=False):
        if clean:
            self.clean()

        os.makedirs(self.build_dir, exist_ok=True)

        sources = [
            os.path.join(self.src_dir, 'VoterBenchmark.java'),
            os.path.join(self.src_dir, 'AsyncVoter.java')
        ]

        classpath = f"{self.voltdb_home}/voltdb/*:{self.voltdb_home}/lib/*"

        VOLT.Java.compile(sources, classpath)

    @VOLT.Command.decorator
    def clean(self):
        if os.path.exists(self.build_dir):
            shutil.rmtree(self.build_dir)

    @VOLT.Command.decorator
    def server(self, mode='localhost'):
        VOLT.Server.start(classpath=self.build_dir)

    @VOLT.Command.decorator
    def run_async(self, clients=10, duration=60):
        cmd = [
            'java', 
            '-cp', f"{self.build_dir}:{self.voltdb_home}/voltdb/*:{self.voltdb_home}/lib/*",
            'AsyncVoter',
            str(clients),
            str(duration)
        ]
        subprocess.run(cmd, check=True)

    @VOLT.Command.decorator
    def run_sync(self, clients=10, duration=60):
        cmd = [
            'java', 
            '-cp', f"{self.build_dir}:{self.voltdb_home}/voltdb/*:{self.voltdb_home}/lib/*",
            'VoterBenchmark',
            '--sync',
            str(clients),
            str(duration)
        ]
        subprocess.run(cmd, check=True)

def main():
    parser = argparse.ArgumentParser(description='VoltDB Voter Benchmark Runner')
    parser.add_argument('command', choices=['build', 'clean', 'server', 'async', 'sync'])
    parser.add_argument('--clients', type=int, default=10)
    parser.add_argument('--duration', type=int, default=60)
    args = parser.parse_args()

    runner = VoterBenchmarkRunner()

    command_map = {
        'build': runner.build,
        'clean': runner.clean,
        'server': runner.server,
        'async': runner.run_async,
        'sync': runner.run_sync
    }

    if args.command in ['async', 'sync']:
        command_map[args.command](clients=args.clients, duration=args.duration)
    else:
        command_map[args.command]()

if __name__ == '__main__':
    main()

from flask import Flask, Blueprint, request, render_template, redirect, make_response
from mongoengine import Document, StringField, DateTimeField, connect
from functools import wraps
import datetime
import json
import uuid

# MongoDB connection setup
connect('user_authentication_db', host='localhost', port=27017)

class User(Document):
    username = StringField(required=True, unique=True)
    password = StringField(required=True)
    role = StringField(default='user')

class SessionStorage(Document):
    session_id = StringField(primary_key=True)
    user_id = StringField(required=True)
    created_at = DateTimeField(default=datetime.datetime.utcnow)
    expires_at = DateTimeField(required=True)

class UserAuth:
    def __init__(self):
        self.auth = Blueprint('auth', __name__)
        self.setup_routes()

    def setup_routes(self):
        self.auth.route('/login', methods=['GET'])(self.get)
        self.auth.route('/login', methods=['POST'])(self.post)
        self.auth.route('/logout')(self.logout)

    def get(self):
        return render_template('login.html')

    def post(self):
        username = request.form.get('username')
        password = request.form.get('password')

        user = User.objects(username=username, password=password).first()
        if user:
            session_id = str(uuid.uuid4())
            expires_at = datetime.datetime.utcnow() + datetime.timedelta(hours=2)

            session = SessionStorage(
                session_id=session_id,
                user_id=str(user.id),
                expires_at=expires_at
            )
            session.save()

            response = make_response(redirect('/dashboard'))
            response.set_cookie('session_id', session_id, httponly=True, secure=True)
            return response

        return render_template('login.html', error='Invalid credentials')

    def logout(self):
        session_id = request.cookies.get('session_id')
        if session_id:
            SessionStorage.objects(session_id=session_id).delete()

        response = make_response(redirect('/login'))
        response.delete_cookie('session_id')
        return response

def requires_auth(role='user'):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            session_id = request.cookies.get('session_id')

            if not session_id:
                return redirect('/login')

            session = SessionStorage.objects(session_id=session_id, 
                                             expires_at__gt=datetime.datetime.utcnow()).first()

            if not session:
                return redirect('/login')

            user = User.objects(id=session.user_id).first()

            if role == 'admin' and user.role != 'admin':
                return 'Unauthorized', 403

            return f(*args, **kwargs)
        return decorated_function
    return decorator

def create_default_users():
    if not User.objects(username='admin'):
        admin = User(username='admin', password='admin123', role='admin')
        admin.save()

    if not User.objects(username='user'):
        user = User(username='user', password='user123')
        user.save()

def create_app():
    app = Flask(__name__)
    user_auth = UserAuth()
    app.register_blueprint(user_auth.auth)

    create_default_users()
    return app

if __name__ == '__main__':
    app = create_app()
    app.run(debug=True)

import os
import selinux
import tempfile
import unittest
import blivet

class SELinuxContextTestCase(unittest.TestCase):
    LOST_AND_FOUND_CONTEXT = "system_u:object_r:lost_found_t:s0"

    def setUp(self):
        self.original_installer_mode = blivet.flags.installer_mode
        blivet.flags.installer_mode = True
        self.temp_mount_point = tempfile.mkdtemp()
        self.selinux_enabled = selinux.is_selinux_enabled()

    def tearDown(self):
        blivet.flags.installer_mode = self.original_installer_mode
        os.rmdir(self.temp_mount_point)

    def create_loopback_device(self, filesystem_type, size_mb=100):
        loopback_file = tempfile.mktemp(prefix='selinux_test_')

        with open(loopback_file, 'wb') as f:
            f.seek(size_mb * 1024 * 1024 - 1)
            f.write(b'\0')

        os.system(f"mkfs.{filesystem_type} {loopback_file}")
        return loopback_file

    def mount(self, device_path, mount_point):
        os.system(f"mount {device_path} {mount_point}")

    def unmount(self, mount_point):
        os.system(f"umount {mount_point}")

    def verify_lost_and_found_context(self, mount_point):
        lost_and_found_path = os.path.join(mount_point, 'lost+found')

        if not os.path.exists(lost_and_found_path):
            self.fail(f"lost+found directory not found in {mount_point}")

        if self.selinux_enabled:
            actual_context = selinux.getfilecon(lost_and_found_path)[1]
            self.assertEqual(actual_context, self.LOST_AND_FOUND_CONTEXT)

    def testMountingExt2FS(self):
        if not self.selinux_enabled:
            self.skipTest("SELinux not enabled")

        ext2_device = self.create_loopback_device('ext2')

        try:
            self.mount(ext2_device, self.temp_mount_point)
            self.verify_lost_and_found_context(self.temp_mount_point)
        finally:
            self.unmount(self.temp_mount_point)
            os.unlink(ext2_device)

    def testMountingXFS(self):
        if not self.selinux_enabled:
            self.skipTest("SELinux not enabled")

        xfs_device = self.create_loopback_device('xfs')

        try:
            self.mount(xfs_device, self.temp_mount_point)
            self.verify_lost_and_found_context(self.temp_mount_point)
        finally:
            self.unmount(self.temp_mount_point)
            os.unlink(xfs_device)

class Ext2FS:
    def __init__(self, size_mb=100):
        self.size = size_mb
        self.loopback_file = None

class XFS:
    def __init__(self, size_mb=100):
        self.size = size_mb
        self.loopback_file = None

if __name__ == '__main__':
    unittest.main()

import os
import math
import bpy
from mathutils import Matrix, Vector

class AttachNode:
    def __init__(self, name, position, orientation):
        self.name = name
        self.position = position
        self.orientation = orientation

class ObjectExporter:
    def __init__(self):
        self.exported_objects = set()
        self.type_handlers = {
            'MESH': self.export_mesh,
            'EMPTY': self.handle_empty,
            'ARMATURE': self.export_armature
        }

    def is_group_root(self, obj):
        return (obj.parent is None or 
                obj.parent.type not in ['MESH', 'EMPTY', 'ARMATURE'])

    def collect_objects(self, collection, root_only=False):
        objects = []
        for obj in collection.all_objects:
            if root_only and not self.is_group_root(obj):
                continue
            if obj.type in self.type_handlers:
                objects.append(obj)
        return sorted(objects, key=lambda x: x.name)

    def get_global_transform(self, obj):
        return obj.matrix_world.copy()

    def extract_attach_nodes(self, obj):
        nodes = []
        for child in obj.children:
            if child.type == 'EMPTY' and child.name.startswith('node_'):
                transform = self.get_global_transform(child)
                nodes.append(AttachNode(
                    child.name[5:],
                    transform.translation,
                    transform.to_quaternion()
                ))
        return nodes

    def export_mesh(self, obj):
        if obj in self.exported_objects:
            return None

        mesh_data = {
            'name': obj.name,
            'vertices': [],
            'faces': [],
            'transform': self.get_global_transform(obj),
            'attach_nodes': self.extract_attach_nodes(obj)
        }

        mesh = obj.data
        mesh.calc_loop_triangles()

        for vertex in mesh.vertices:
            mesh_data['vertices'].append(vertex.co)

        for triangle in mesh.loop_triangles:
            mesh_data['faces'].append(triangle.vertices)

        self.exported_objects.add(obj)
        return mesh_data

    def handle_empty(self, obj):
        if obj in self.exported_objects or not obj.name.startswith('transform_'):
            return None

        empty_data = {
            'name': obj.name[10:],
            'transform': self.get_global_transform(obj),
            'attach_nodes': self.extract_attach_nodes(obj)
        }

        self.exported_objects.add(obj)
        return empty_data

    def export_armature(self, obj):
        if obj in self.exported_objects:
            return None

        armature_data = {
            'name': obj.name,
            'bones': [],
            'transform': self.get_global_transform(obj)
        }

        for bone in obj.data.bones:
            bone_info = {
                'name': bone.name,
                'head': bone.head_local,
                'tail': bone.tail_local,
                'matrix': bone.matrix_local
            }
            armature_data['bones'].append(bone_info)

        self.exported_objects.add(obj)
        return armature_data

    def export_collection(self, collection):
        exported_collection = {
            'name': collection.name,
            'objects': []
        }

        objects = self.collect_objects(collection)
        for obj in objects:
            handler = self.type_handlers.get(obj.type)
            if handler:
                object_data = handler(obj)
                if object_data:
                    exported_collection['objects'].append(object_data)

        return exported_collection

import copy
import re
import unittest

class Record:
    def __init__(self, initial_data=None):
        self._data = initial_data or {}

    def set(self, key, value):
        parts = key.split('.')
        current = self._data
        for part in parts[:-1]:
            current = current.setdefault(part, {})
        current[parts[-1]] = value

    def get(self, key, default=None):
        parts = key.split('.')
        current = self._data
        try:
            for part in parts:
                current = current[part]
            return current
        except (KeyError, TypeError):
            return default

    def delete(self, key):
        parts = key.split('.')
        current = self._data
        for part in parts[:-1]:
            current = current[part]
        del current[parts[-1]]

    def sub(self, prefix=''):
        result = {}
        for key, value in self._data.items():
            if prefix == '' or key.startswith(prefix):
                result[key] = value
        return Record(result)

    def children(self, prefix=''):
        result = []
        for key in self._data.keys():
            if prefix == '' or key.startswith(prefix):
                result.append(key)
        return result

    def __eq__(self, other):
        return self._data == other._data

    def __getitem__(self, key):
        return self.get(key)

    def __setitem__(self, key, value):
        self.set(key, value)

    def __delitem__(self, key):
        self.delete(key)

class RecordAttr:
    def __init__(self, initial_data=None):
        self._record = Record(initial_data)

    def __getattr__(self, key):
        return self._record.get(key)

    def __setattr__(self, key, value):
        if key == '_record':
            super().__setattr__(key, value)
        else:
            self._record.set(key, value)

    def __delattr__(self, key):
        if key == '_record':
            raise AttributeError("Cannot delete _record attribute")
        self._record.delete(key)

class TestRecord(unittest.TestCase):
    def setUp(self):
        self.record = Record()

    def test_basic_operations(self):
        self.record.set('key1', 'value1')
        self.assertEqual(self.record.get('key1'), 'value1')
        self.record.delete('key1')
        self.assertIsNone(self.record.get('key1'))

    def test_nested_operations(self):
        self.record.set('level1.level2.key', 'nested_value')
        self.assertEqual(self.record.get('level1.level2.key'), 'nested_value')

    def test_sub_method(self):
        self.record.set('prefix.key1', 1)
        self.record.set('prefix.key2', 2)
        sub_record = self.record.sub('prefix')
        self.assertEqual(len(sub_record.children()), 2)

    def test_children_method(self):
        self.record.set('a.b.c', 1)
        self.record.set('a.b.d', 2)
        children = self.record.children('a.b')
        self.assertIn('c', children)
        self.assertIn('d', children)

def main():
    unittest.main()

if __name__ == '__main__':
    main()

import json
from bottle import route, run, request, response
from pyrouted.util import (
    config_load, config_save,
    source_add, source_del, source_restart
)

class APIv1:
    def __init__(self, ndb, config):
        self.ndb = ndb
        self.config = config
        self._register_routes()

    def _register_routes(self):
        route('/v1/sources', method='GET', callback=self.sources_list)
        route('/v1/sources', method='POST', callback=self.sources_add)
        route('/v1/sources/<name>/restart', method='POST', callback=self.sources_restart)
        route('/v1/sources/<name>', method='DELETE', callback=self.sources_del)
        route('/v1/config', method='GET', callback=self.config_get)
        route('/v1/config', method='PUT', callback=self.config_dump)
        route('/v1/view/<category>', method='GET', callback=self.view)
        route('/v1/query', method='POST', callback=self.query)

    def sources_list(self):
        try:
            sources = self.ndb.sources()
            return json.dumps(sources)
        except Exception as e:
            response.status = 500
            return json.dumps({"error": str(e)})

    def sources_add(self):
        try:
            data = request.json
            result = source_add(data)
            return json.dumps(result)
        except Exception as e:
            response.status = 400
            return json.dumps({"error": str(e)})

    def sources_restart(self, name):
        try:
            result = source_restart(name)
            return json.dumps(result)
        except Exception as e:
            response.status = 500
            return json.dumps({"error": str(e)})

    def sources_del(self, name):
        try:
            result = source_del(name)
            return json.dumps(result)
        except Exception as e:
            response.status = 404
            return json.dumps({"error": str(e)})

    def config_get(self):
        try:
            current_config = config_load()
            return json.dumps(current_config)
        except Exception as e:
            response.status = 500
            return json.dumps({"error": str(e)})

    def config_dump(self):
        try:
            data = request.json
            config_save(data)
            return json.dumps({"status": "success"})
        except Exception as e:
            response.status = 400
            return json.dumps({"error": str(e)})

    def view(self, category):
        try:
            valid_categories = [
                "interfaces", "addresses", "routes", 
                "neighbors", "vlans", "bridges"
            ]
            if category not in valid_categories:
                raise ValueError("Invalid category")

            method = getattr(self.ndb, category)
            result = method()
            return json.dumps(result)
        except Exception as e:
            response.status = 404
            return json.dumps({"error": str(e)})

    def query(self):
        try:
            query_params = request.json
            topology_query = query_params.get('query')

            if not topology_query:
                raise ValueError("No query provided")

            result = self.ndb.topology_query(topology_query)
            return json.dumps(result)
        except Exception as e:
            response.status = 400
            return json.dumps({"error": str(e)})

def create_api(ndb, config):
    return APIv1(ndb, config)

def main():
    ndb = None  # Replace with actual NDB initialization
    config = None  # Replace with actual config initialization
    api = create_api(ndb, config)
    run(host='localhost', port=8080, debug=True)

if __name__ == '__main__':
    main()

import ubelt as ub
import pandas as pd
import hashlib
import time
import random
import numpy as np

try:
    import kwplot
    HAS_KWPLOT = True
except ImportError:
    HAS_KWPLOT = False

HASHERS = [
    'md5', 
    'sha1', 
    'sha256', 
    'blake2b', 
    'sha512'
]

def generate_test_data(scale):
    """Generate variable complexity test data."""
    base_data = {
        'small': b'Hello World',
        'medium': b'Complex Test String with Multiple Attributes',
        'large': b'Large Random Data Generation for Performance Testing' * 1000,
        'huge': b'Extreme Scale Data Generation' * 10000
    }
    return base_data.get(scale, base_data['medium'])

def benchmark_hash_data(hasher_name, data, num_trials=10):
    """Benchmark a specific hash function's performance."""
    hasher = getattr(hashlib, hasher_name, None)
    if not hasher:
        return None

    times = []
    for _ in range(num_trials):
        start_time = time.perf_counter()
        hasher(data).hexdigest()
        end_time = time.perf_counter()
        times.append(end_time - start_time)

    return {
        'mean_time': np.mean(times),
        'std_time': np.std(times),
        'min_time': np.min(times),
        'max_time': np.max(times)
    }

def run_comprehensive_hash_benchmark(scales=['small', 'medium', 'large'], 
                                     hashers=None):
    """Comprehensive hash function performance analysis."""
    hashers = hashers or HASHERS
    results = {}

    for scale in ub.ProgIter(scales):
        test_data = generate_test_data(scale)
        results[scale] = {}

        for hasher_name in hashers:
            performance = benchmark_hash_data(hasher_name, test_data)
            results[scale][hasher_name] = performance

    return results

def analyze_hash_performance(benchmark_results):
    """Convert benchmark results to performance DataFrame."""
    performance_data = []
    for scale, hasher_metrics in benchmark_results.items():
        for hasher, metrics in hasher_metrics.items():
            if metrics:
                performance_data.append({
                    'Scale': scale,
                    'Hasher': hasher,
                    'Mean Time': metrics['mean_time'],
                    'Std Time': metrics['std_time']
                })

    return pd.DataFrame(performance_data)

def visualize_hash_performance(performance_df):
    """Optional visualization of hash performance."""
    if not HAS_KWPLOT:
        print("Kwplot not available. Skipping visualization.")
        return

    plt = kwplot.plt
    kwplot.autompl()

    plt.figure(figsize=(10, 6))
    for scale in performance_df['Scale'].unique():
        subset = performance_df[performance_df['Scale'] == scale]
        plt.bar(subset['Hasher'], subset['Mean Time'], label=scale)

    plt.title('Hash Function Performance Comparison')
    plt.ylabel('Mean Execution Time (seconds)')
    plt.xlabel('Hash Algorithms')
    plt.legend()
    plt.tight_layout()
    plt.show()

def main():
    """Main execution for hash benchmarking."""
    benchmark_results = run_comprehensive_hash_benchmark()
    performance_df = analyze_hash_performance(benchmark_results)

    print(performance_df)

    if HAS_KWPLOT:
        visualize_hash_performance(performance_df)

if __name__ == '__main__':
    main()

import os
import string
import re

class CodeLibraryGenerator:
    def __init__(self, base_directory, output_file, languages=['cpp', 'java']):
        self.base_directory = base_directory
        self.output_file = output_file
        self.languages = languages
        self.file_extensions = {
            'cpp': ['.cpp', '.h', '.cc', '.hpp'],
            'java': ['.java']
        }
        self.excluded_dirs = ['.git', '__pycache__', 'node_modules']
        self.excluded_files = ['.DS_Store', 'thumbs.db']

    def is_valid_source_file(self, filename):
        file_extension = os.path.splitext(filename)[1].lower()
        return any(file_extension in ext_list for ext_list in self.file_extensions.values())

    def generate_section_title(self, directory):
        normalized_path = directory.replace(self.base_directory, '').strip(os.path.sep)
        return string.capwords(normalized_path.replace(os.path.sep, ' '), sep=' ')

    def apply_syntax_highlighting(self, filename, language):
        syntax_map = {
            'cpp': 'CPP',
            'java': 'Java'
        }
        return syntax_map.get(language, 'text')

    def escape_latex_special_chars(self, code):
        special_chars = {
            '&': r'\&',
            '%': r'\%',
            '$': r'\$',
            '#': r'\#',
            '_': r'\_',
            '{': r'\{',
            '}': r'\}',
            '~': r'\textasciitilde{}',
            '^': r'\^{}',
            '\\': r'\textbackslash{}'
        }
        for char, replacement in special_chars.items():
            code = code.replace(char, replacement)
        return code

    def generate_latex_document(self):
        with open(self.output_file, 'w', encoding='utf-8') as f:
            # LaTeX document header and configuration
            f.write(r'''\documentclass[12pt]{article}
\usepackage{listings}
\usepackage{geometry}
\usepackage{hyperref}
\usepackage{color}

\lstdefinestyle{codestyle}{
    basicstyle=\ttfamily\small,
    breakatwhitespace=false,
    breaklines=true,
    captionpos=b,
    keepspaces=true,
    numbers=left,
    numbersep=5pt,
    showspaces=false,
    showstringspaces=false,
    showtabs=false,
    tabsize=4
}

\lstset{style=codestyle}

\begin{document}
\tableofcontents
\newpage
''')

            # Traverse directory structure
            for x, y, z in os.walk(self.base_directory):
                if any(excluded in x for excluded in self.excluded_dirs):
                    continue

                source_files = [
                    file for file in z 
                    if self.is_valid_source_file(file) and 
                    file not in self.excluded_files
                ]

                if source_files:
                    section_title = self.generate_section_title(x)
                    f.write(f'\\section{{{section_title}}}\n')

                    for filename in sorted(source_files):
                        filepath = os.path.join(x, filename)
                        file_language = next(
                            (lang for lang, extensions in self.file_extensions.items() 
                             if os.path.splitext(filename)[1].lower() in extensions), 
                            'text'
                        )

                        listing_title = f"{section_title} - {filename}"
                        syntax_language = self.apply_syntax_highlighting(filename, file_language)

                        f.write(f'\\subsection{{{listing_title}}}\n')
                        f.write('\\begin{lstlisting}[language=' + syntax_language + ']\n')

                        try:
                            with open(filepath, 'r', encoding='utf-8') as source_file:
                                code_content = source_file.read()
                                escaped_code = self.escape_latex_special_chars(code_content)
                                f.write(escaped_code)
                        except Exception as e:
                            print(f"Error reading {filepath}: {e}")

                        f.write('\n\\end{lstlisting}\n\n')

            # Close LaTeX document
            f.write(r'\end{document}')

    def compile_document(self):
        try:
            os.system(f'pdflatex {self.output_file}')
        except Exception as e:
            print(f"LaTeX compilation error: {e}")

def main():
    generator = CodeLibraryGenerator(
        base_directory='/path/to/source/code',
        output_file='code_library.tex',
        languages=['cpp', 'java']
    )
    generator.generate_latex_document()
    generator.compile_document()

if __name__ == '__main__':
    main()

import re
from troposphere import (
    Template, Ref, GetAtt, Output, Sub, Join,
    Tags, Parameter
)
from troposphere.ec2 import (
    SecurityGroup, NetworkAcl, 
    NetworkAclEntry, SubnetNetworkAclAssociation
)
from troposphere.efs import (
    FileSystem, MountTarget, 
    BackupPolicy
)
from create import generate_unique_name

class AclFactory:
    @staticmethod
    def create_network_acl(template, vpc_id, environment):
        network_acl = template.add_resource(
            NetworkAcl(
                f"{environment}EFSNetworkACL",
                VpcId=vpc_id,
                Tags=Tags(
                    Name=Sub(f"${environment}-efs-network-acl"),
                    Environment=environment
                )
            )
        )
        return network_acl

    @staticmethod
    def configure_acl_entries(template, network_acl):
        inbound_rules = [
            NetworkAclEntry(
                f"InboundTCPRule{i}",
                NetworkAclId=Ref(network_acl),
                RuleNumber=100 + i,
                Protocol=6,
                RuleAction="allow",
                Egress=False,
                CidrBlock="0.0.0.0/0",
                PortRange={"From": 2049, "To": 2049}
            ) for i in range(2)
        ]

        outbound_rules = [
            NetworkAclEntry(
                f"OutboundTCPRule{i}",
                NetworkAclId=Ref(network_acl),
                RuleNumber=100 + i,
                Protocol=6,
                RuleAction="allow",
                Egress=True,
                CidrBlock="0.0.0.0/0",
                PortRange={"From": 2049, "To": 2049}
            ) for i in range(2)
        ]

        return template.add_resource(inbound_rules + outbound_rules)

def assoc_nacl_subnet(template, network_acl, subnets):
    return [
        template.add_resource(
            SubnetNetworkAclAssociation(
                f"NACLAssoc{subnet.title}",
                SubnetId=Ref(subnet),
                NetworkAclId=Ref(network_acl)
            )
        ) for subnet in subnets
    ]

def export_ref(resource, export_name):
    return Output(
        export_name,
        Description=f"{export_name} Reference",
        Value=Ref(resource),
        Export={"Name": Sub(f"${{AWS::StackName}}-{export_name}")}
    )

def efs_setup(template, ops, app_cfn_options):
    filesystem = template.add_resource(
        FileSystem(
            generate_unique_name("EFSFileSystem"),
            Encrypted=True,
            PerformanceMode="generalPurpose",
            ThroughputMode="bursting",
            BackupPolicy=BackupPolicy(Status="ENABLED"),
            Tags=Tags(
                Name=Sub("${environment}-efs"),
                Environment=ops.environment
            )
        )
    )

    security_group = template.add_resource(
        SecurityGroup(
            f"{ops.environment}EFSSecurityGroup",
            GroupDescription="EFS Security Group",
            VpcId=ops.vpc_id,
            SecurityGroupIngress=[
                {"IpProtocol": "tcp", "FromPort": 2049, "ToPort": 2049, "CidrIp": "0.0.0.0/0"}
            ],
            Tags=Tags(Name=Sub("${environment}-efs-sg"))
        )
    )

    mount_targets = [
        template.add_resource(
            MountTarget(
                f"EFSMountTarget{subnet.title}",
                FileSystemId=Ref(filesystem),
                SubnetId=Ref(subnet),
                SecurityGroups=[Ref(security_group)]
            )
        ) for subnet in app_cfn_options.get('subnets', [])
    ]

    template.add_output([
        export_ref(filesystem, "EFSFilesystemId"),
        export_ref(security_group, "EFSSecurityGroupId")
    ])

    network_acl = AclFactory.create_network_acl(template, ops.vpc_id, ops.environment)
    AclFactory.configure_acl_entries(template, network_acl)
    assoc_nacl_subnet(template, network_acl, app_cfn_options.get('subnets', []))

    return filesystem, security_group, mount_targets

import pymongo
from datetime import datetime, timedelta
from typing import List, Dict, Optional
import logging
import uuid

class TimeQuery:
    def __init__(self, start_time=None, end_time=None):
        self.start_time = start_time or datetime.min
        self.end_time = end_time or datetime.max

class Stop:
    def __init__(self, location, timestamp, stop_type):
        self.location = location
        self.timestamp = timestamp
        self.stop_type = stop_type

class Section:
    def __init__(self, start_location, end_location, start_time, end_time, transportation_mode):
        self.start_location = start_location
        self.end_location = end_location
        self.start_time = start_time
        self.end_time = end_time
        self.transportation_mode = transportation_mode

class Trip:
    def __init__(self, user_id, start_time, end_time, sections=None, stops=None):
        self.trip_id = str(uuid.uuid4())
        self.user_id = user_id
        self.start_time = start_time
        self.end_time = end_time
        self.sections = sections or []
        self.stops = stops or []

class TripManager:
    def __init__(self, connection_string, database_name):
        self.client = pymongo.MongoClient(connection_string)
        self.db = self.client[database_name]
        self.trips_collection = self.db['trips']
        self.logger = logging.getLogger(__name__)

    def create_new_trip(self, user_id, start_time, end_time, sections=None, stops=None):
        try:
            trip = Trip(user_id, start_time, end_time, sections, stops)
            result = self.save_trip(trip)
            return trip
        except Exception as e:
            self.logger.error(f"Error creating trip: {e}")
            raise

    def save_trip(self, trip):
        trip_dict = {
            'trip_id': trip.trip_id,
            'user_id': trip.user_id,
            'start_time': trip.start_time,
            'end_time': trip.end_time,
            'sections': [vars(section) for section in trip.sections],
            'stops': [vars(stop) for stop in trip.stops]
        }
        return self.trips_collection.insert_one(trip_dict)

    def get_trips(self, user_id, time_query=None):
        query = {'user_id': user_id}
        if time_query:
            query.update({
                'start_time': {'$gte': time_query.start_time},
                'end_time': {'$lte': time_query.end_time}
            })

        trips_cursor = self.trips_collection.find(query)
        return [self._convert_to_trip_object(trip) for trip in trips_cursor]

    def get_trip(self, trip_id):
        trip_document = self.trips_collection.find_one({'trip_id': trip_id})
        return self._convert_to_trip_object(trip_document) if trip_document else None

    def get_sections_for_trip(self, trip_id):
        trip = self.get_trip(trip_id)
        return trip.sections if trip else []

    def get_stops_for_trip(self, trip_id):
        trip = self.get_trip(trip_id)
        return trip.stops if trip else []

    def get_aggregate_trips(self, user_id, time_query=None):
        pipeline = [
            {'$match': {'user_id': user_id}},
            {'$group': {
                '_id': '$transportation_mode',
                'total_trips': {'$sum': 1},
                'total_duration': {'$sum': {'$subtract': ['$end_time', '$start_time']}}
            }}
        ]
        return list(self.trips_collection.aggregate(pipeline))

    def get_timeline_for_trip(self, trip_id):
        trip = self.get_trip(trip_id)
        if not trip:
            return None

        timeline = []
        for section in trip.sections:
            timeline.append({
                'type': 'section',
                'start_time': section.start_time,
                'end_time': section.end_time,
                'transportation_mode': section.transportation_mode
            })

        for stop in trip.stops:
            timeline.append({
                'type': 'stop',
                'timestamp': stop.timestamp,
                'stop_type': stop.stop_type
            })

        return sorted(timeline, key=lambda x: x.get('start_time', x.get('timestamp')))

    def _convert_to_trip_object(self, trip_document):
        sections = [Section(**section) for section in trip_document.get('sections', [])]
        stops = [Stop(**stop) for stop in trip_document.get('stops', [])]
        trip = Trip(
            user_id=trip_document['user_id'],
            start_time=trip_document['start_time'],
            end_time=trip_document['end_time'],
            sections=sections,
            stops=stops
        )
        trip.trip_id = trip_document['trip_id']
        return trip

import numpy as np
import json
import os
import pandas as pd
import todsynth
import copy
import typing
from typing import Dict, List, Union, Optional

class Calibrator:
    def __init__(self, uid: str = None, initial_coeffs: np.ndarray = None):
        self.__uid = uid or todsynth.generate_unique_id()
        self.coeffs = initial_coeffs if initial_coeffs is not None else np.zeros(10)
        self.info: Dict[str, Union[str, int, float]] = {}
        self.__version = "1.2.0"
        self.__metadata_version = 1

    def setCoeffs(self, coeffs: np.ndarray, validate: bool = True) -> None:
        """
        Set calibration coefficients with optional validation
        """
        if validate:
            if not isinstance(coeffs, np.ndarray):
                raise TypeError("Coefficients must be numpy array")

            if coeffs.size > 20:
                raise ValueError("Maximum coefficient array size exceeded")

        self.coeffs = np.copy(coeffs)

    def getCoeffs(self, copy_mode: bool = True) -> np.ndarray:
        """
        Retrieve calibration coefficients with optional deep copy
        """
        return np.copy(self.coeffs) if copy_mode else self.coeffs

    def updateInfo(self, key: str, value: Union[str, int, float]) -> None:
        """
        Update calibration metadata information
        """
        self.info[key] = value

    def storeInPath(self, filepath: str, format: str = 'json') -> bool:
        """
        Store calibration data in specified file format
        """
        try:
            data = {
                'uid': self.__uid,
                'coeffs': self.coeffs.tolist(),
                'info': self.info,
                'version': self.__version
            }

            if format.lower() == 'json':
                with open(filepath, 'w') as f:
                    json.dump(data, f, indent=4)

            elif format.lower() == 'csv':
                df = pd.DataFrame({
                    'uid': [self.__uid],
                    'coeffs': [self.coeffs.tolist()],
                    'version': [self.__version]
                })
                df.to_csv(filepath, index=False)

            else:
                raise ValueError("Unsupported file format")

            return True

        except Exception as e:
            print(f"Storage error: {e}")
            return False

    def readFromPath(self, filepath: str, format: str = 'json') -> bool:
        """
        Read calibration data from specified file
        """
        try:
            if format.lower() == 'json':
                with open(filepath, 'r') as f:
                    data = json.load(f)
                    self.__uid = data.get('uid', self.__uid)
                    self.coeffs = np.array(data.get('coeffs', []))
                    self.info = data.get('info', {})

            elif format.lower() == 'csv':
                df = pd.read_csv(filepath)
                self.__uid = df['uid'].iloc[0]
                self.coeffs = np.array(eval(df['coeffs'].iloc[0]))

            return True

        except Exception as e:
            print(f"Reading error: {e}")
            return False

    def transform(self, raw_data: np.ndarray) -> np.ndarray:
        """
        Transform raw data using calibration coefficients
        """
        if len(self.coeffs) == 0:
            return raw_data

        return np.polyval(self.coeffs, raw_data)

    def validate(self) -> bool:
        """
        Validate calibration data integrity
        """
        return (
            len(self.coeffs) > 0 and
            not np.all(self.coeffs == 0) and
            self.__uid is not None
        )

    def export_to_dict(self) -> Dict:
        """
        Export calibration data as dictionary
        """
        return {
            'uid': self.__uid,
            'coeffs': self.coeffs.tolist(),
            'info': self.info,
            'version': self.__version
        }

    @classmethod
    def from_dict(cls, data: Dict) -> 'Calibrator':
        """
        Create Calibrator instance from dictionary
        """
        calibrator = cls(
            uid=data.get('uid'),
            initial_coeffs=np.array(data.get('coeffs', []))
        )
        calibrator.info = data.get('info', {})
        return calibrator

from django.db import models
from django.db.models.signals import post_save, post_delete
from django.dispatch import receiver
from model_utils.models import TimeStampedModel
from django.utils.translation import gettext_lazy as _
from jsonfield import JSONField

class Event(TimeStampedModel):
    ACTIONS = (
        ('create', _('Created')),
        ('update', _('Updated')),
        ('delete', _('Deleted')),
        ('activate', _('Activated')),
        ('deactivate', _('Deactivated')),
    )

    package = models.ForeignKey(
        'Package', 
        on_delete=models.CASCADE, 
        related_name='events'
    )
    version = models.CharField(max_length=100, null=True, blank=True)
    action = models.CharField(max_length=20, choices=ACTIONS)
    data = JSONField(null=True, blank=True)

    def __str__(self):
        return f"{self.package} - {self.get_action_display()} at {self.created}"

    class Meta:
        verbose_name = _('Event')
        verbose_name_plural = _('Events')
        ordering = ['-created']

class Package(models.Model):
    name = models.CharField(max_length=200)
    description = models.TextField(blank=True)
    is_visible = models.BooleanField(default=True)

    def __str__(self):
        return self.name

class Release(models.Model):
    package = models.ForeignKey(Package, on_delete=models.CASCADE, related_name='releases')
    version = models.CharField(max_length=100)
    is_active = models.BooleanField(default=True)

    def __str__(self):
        return f"{self.package.name} {self.version}"

class ReleaseFile(models.Model):
    release = models.ForeignKey(Release, on_delete=models.CASCADE, related_name='files')
    filename = models.CharField(max_length=255)
    size = models.IntegerField()
    md5_digest = models.CharField(max_length=32)

    def __str__(self):
        return self.filename

@receiver(post_save, sender=Package)
def history_package_create(sender, instance, created, **kwargs):
    if created:
        Event.objects.create(
            package=instance,
            action='create',
            data={
                'name': instance.name,
                'description': instance.description
            }
        )

@receiver(post_delete, sender=Package)
def history_package_delete(sender, instance, **kwargs):
    Event.objects.create(
        package=instance,
        action='delete',
        data={
            'name': instance.name
        }
    )

@receiver(post_save, sender=Release)
def history_release_update(sender, instance, created, **kwargs):
    action = 'create' if created else 'update'
    Event.objects.create(
        package=instance.package,
        version=instance.version,
        action=action,
        data={
            'version': instance.version,
            'is_active': instance.is_active
        }
    )

@receiver(post_save, sender=ReleaseFile)
def history_releasefile_update(sender, instance, created, **kwargs):
    action = 'create' if created else 'update'
    Event.objects.create(
        package=instance.release.package,
        version=instance.release.version,
        action=action,
        data={
            'filename': instance.filename,
            'size': instance.size,
            'md5_digest': instance.md5_digest
        }
    )

import click
import random
import sys
from typing import List, Dict
from newsfeeds import NewsFetcher
from config import GlobalConfig
from rich.console import Console
from rich.table import Table
from webbrowser import open as web_open

class Story:
    def __init__(self, title: str, source: str, section: str, abstract: str, url: str):
        self.title = title
        self.source = source
        self.section = section
        self.abstract = abstract
        self.url = url

class NewsAggregator:
    def __init__(self, config: GlobalConfig):
        self.config = config
        self.console = Console()
        self.news_fetcher = NewsFetcher()

    def fetch_stories(self) -> List[Story]:
        try:
            raw_stories = self.news_fetcher.get_stories()
            return [Story(**story) for story in raw_stories]
        except Exception as e:
            self.console.print(f"[bold red]Error fetching stories: {e}[/bold red]")
            return []

    def mixer(self, story_list: List[Story], sample_size: int = 10) -> List[Story]:
        if not story_list:
            return []
        return random.sample(story_list, min(sample_size, len(story_list)))

    def default_display(self, mixed_story_list: List[Story]):
        table = Table(title="Random News Stories")
        table.add_column("Index", style="cyan")
        table.add_column("Title", style="magenta")
        table.add_column("Source", style="green")
        table.add_column("Section", style="blue")

        for index, story in enumerate(mixed_story_list, 1):
            table.add_row(
                str(index), 
                story.title[:50] + "...", 
                story.source, 
                story.section
            )

        self.console.print(table)

    def story_interaction(self, mixed_story_list: List[Story]):
        while True:
            try:
                option = click.prompt("Select story number (0 to exit)", type=int)

                if option == 0:
                    break

                if 1 <= option <= len(mixed_story_list):
                    selected_story = mixed_story_list[option - 1]

                    self.console.print(f"\n[bold yellow]Selected Story:[/bold yellow]")
                    self.console.print(f"Title: {selected_story.title}")
                    self.console.print(f"Abstract: {selected_story.abstract}")

                    open_link = click.confirm("Open story link?")
                    if open_link:
                        web_open(selected_story.url)
                else:
                    self.console.print("[bold red]Invalid selection[/bold red]")

            except ValueError:
                self.console.print("[bold red]Please enter a valid number[/bold red]")

@click.command()
@click.option('--sample-size', default=10, help='Number of stories to display')
def main(sample_size):
    config = GlobalConfig()
    aggregator = NewsAggregator(config)

    try:
        story_list = aggregator.fetch_stories()

        if not story_list:
            click.echo("No stories available.")
            sys.exit(1)

        mixed_story_list = aggregator.mixer(story_list, sample_size)

        aggregator.default_display(mixed_story_list)
        aggregator.story_interaction(mixed_story_list)

    except Exception as e:
        click.echo(f"An error occurred: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
